css:
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
@keyframes fadeOut{to{opacity:0}}
@keyframes rise{from{opacity:0;transform:translateY(50px)}to{opacity:1;transform:none}}
@keyframes riseBlur{from{opacity:0;transform:translateY(60px);filter:blur(16px)}to{opacity:1;transform:none;filter:blur(0)}}
@keyframes liftOut{to{opacity:0;transform:translateY(-120px) scale(.94);filter:blur(14px)}}
@keyframes pop{0%{opacity:0;transform:scale(0) rotate(-120deg)}70%{opacity:1;transform:scale(1.1) rotate(6deg)}100%{opacity:1;transform:none}}
@keyframes wipe{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 -10% 0 0)}}
@keyframes drift{0%{transform:translate(0,0) scale(1)}50%{transform:translate(140px,-90px) scale(1.18)}100%{transform:translate(-70px,70px) scale(.94)}}
@keyframes sweep{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.bg{overflow:hidden}
.orb{position:absolute;border-radius:50%;filter:blur(120px);animation:drift 24s ease-in-out 0s both}
.grid{position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);background-size:80px 80px;-webkit-mask-image:radial-gradient(ellipse at center,#000 30%,transparent 75%);mask-image:radial-gradient(ellipse at center,#000 30%,transparent 75%)}
.shot{position:absolute;border-radius:22px;overflow:hidden;border:1px solid rgba(255,255,255,.12);box-shadow:0 50px 140px rgba(0,0,0,.65),0 0 0 1px rgba(0,0,0,.4)}
.shot img{display:block;width:100%;height:100%;object-fit:cover;object-position:top left}
.h{font-family:var(--font-headline);font-weight:900;letter-spacing:-.045em;line-height:.95;color:var(--fg);margin:0}
.p{font-size:38px;color:var(--muted);line-height:1.35;margin:0}

.jbg{background:radial-gradient(ellipse at 50% 115%,#2A1A08 0%,var(--bg) 62%)}
.o1{width:820px;height:820px;background:#F5A524;left:-260px;top:-300px;opacity:.32}
.o2{width:640px;height:640px;background:#FF6B2C;right:-200px;bottom:-240px;opacity:.22;animation-direction:reverse;animation-duration:19s}
.words{display:flex;align-items:center;justify-content:center;gap:40px;animation:liftOut .6s cubic-bezier(.7,0,.84,0) 4.1s forwards}
.words .w{font-size:150px;opacity:0;animation:slam .55s cubic-bezier(.16,1,.3,1) both}
.words .w.a{color:var(--accent)}
@keyframes slam{0%{opacity:0;transform:scale(2.2);filter:blur(30px)}100%{opacity:1;transform:none;filter:none}}
.words-sub{display:flex;align-items:flex-end;justify-content:center;padding-bottom:260px;animation:liftOut .6s cubic-bezier(.7,0,.84,0) 4.1s forwards}
.words-sub .p{font-size:46px;animation:riseBlur .8s cubic-bezier(.16,1,.3,1) 2.4s both}
.words-sub b{color:var(--fg);font-weight:700}

.see{animation:fadeOut .5s ease 6.4s forwards}
.see .copy{position:absolute;left:130px;top:250px;width:620px}
.see .copy .h{font-size:104px;animation:riseBlur .9s cubic-bezier(.16,1,.3,1) .15s both}
.see .copy .p{margin-top:30px;animation:rise .8s cubic-bezier(.16,1,.3,1) .45s both}
.see .shot{left:820px;top:130px;width:1240px;height:775px;transform-origin:left center;animation:tiltIn 1.4s cubic-bezier(.16,1,.3,1) .05s both}
.see .shot img{transform-origin:22% 40%;animation:kb 6s ease-in-out 1.2s both}
@keyframes tiltIn{from{opacity:0;transform:perspective(2600px) rotateY(-38deg) translateX(300px) scale(.9)}to{opacity:1;transform:perspective(2600px) rotateY(-14deg)}}
@keyframes kb{from{transform:scale(1)}to{transform:scale(1.55) translate(4%,6%)}}
.pill{position:absolute;display:flex;align-items:center;gap:16px;padding:20px 30px;border-radius:999px;background:rgba(26,23,20,.92);border:1px solid rgba(245,165,36,.45);color:var(--fg);font-size:32px;font-weight:600;box-shadow:0 20px 60px rgba(0,0,0,.5);animation:pillIn .7s cubic-bezier(.16,1,.3,1) both}
.pill i{width:16px;height:16px;border-radius:50%;background:var(--accent);box-shadow:0 0 18px var(--accent)}
@keyframes pillIn{from{opacity:0;transform:translateY(30px) scale(.85)}to{opacity:1;transform:none}}

.wall{overflow:hidden;animation:fadeOut .5s ease 5s forwards}
.wall .plane{position:absolute;left:50%;top:50%;width:2700px;display:grid;grid-template-columns:repeat(4,1fr);gap:36px;transform:translate(-50%,-50%) perspective(2400px) rotateX(28deg) rotateZ(-10deg);animation:pan 5.5s linear 0s both}
@keyframes pan{from{transform:translate(-50%,-38%) perspective(2400px) rotateX(28deg) rotateZ(-10deg)}to{transform:translate(-50%,-62%) perspective(2400px) rotateX(28deg) rotateZ(-10deg)}}
.wall .tile{aspect-ratio:16/10;border-radius:20px;overflow:hidden;border:1px solid rgba(255,255,255,.12);box-shadow:0 30px 80px rgba(0,0,0,.6);animation:tileIn .8s cubic-bezier(.16,1,.3,1) both}
.wall .tile img{width:100%;height:100%;object-fit:cover;object-position:top left;display:block}
@keyframes tileIn{from{opacity:0;transform:translateY(120px) scale(.85)}to{opacity:1;transform:none}}
.wall .veil{position:absolute;inset:0;background:radial-gradient(ellipse at center,rgba(12,11,10,.92) 0%,rgba(12,11,10,.6) 45%,rgba(12,11,10,.15) 80%);animation:fadeIn .6s ease .8s both}
.wall .mid{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:40px}
.wall .mid .h{font-size:130px;text-align:center;animation:riseBlur .9s cubic-bezier(.16,1,.3,1) 1s both}
.tags{display:flex;gap:18px;flex-wrap:wrap;justify-content:center;max-width:1300px}
.tags span{font-size:30px;font-weight:600;padding:14px 28px;border-radius:999px;background:rgba(245,165,36,.12);border:1px solid rgba(245,165,36,.4);color:#FFD892;animation:pillIn .6s cubic-bezier(.16,1,.3,1) both}

.self{animation:fadeOut .5s ease 3.3s forwards}
.self .copy{position:absolute;left:130px;top:300px;width:820px}
.self .h{font-size:116px;animation:riseBlur .9s cubic-bezier(.16,1,.3,1) .1s both}
.self .h em{font-style:normal;color:var(--accent)}
.self .p{margin-top:32px;animation:rise .8s cubic-bezier(.16,1,.3,1) .45s both}
.self .shot{right:-120px;top:170px;width:1100px;height:690px;animation:tiltR 1.2s cubic-bezier(.16,1,.3,1) .2s both}
@keyframes tiltR{from{opacity:0;transform:perspective(2400px) rotateY(30deg) translateY(200px)}to{opacity:1;transform:perspective(2400px) rotateY(18deg)}}

.end{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:44px}
.logo{display:flex;align-items:center;gap:44px}
.mark{width:200px;height:200px;border-radius:52px;background:linear-gradient(135deg,#FFC14D,#F5A524 45%,#E8741A);display:grid;place-items:center;animation:pop 1s cubic-bezier(.16,1,.3,1) .15s both,glow 2.6s ease-in-out 1.1s both;color:#1A1205}
.mark b{font-size:132px;font-weight:900;letter-spacing:-.06em}
@keyframes glow{0%,100%{box-shadow:0 0 0 0 rgba(245,165,36,0)}50%{box-shadow:0 0 140px 30px rgba(245,165,36,.45)}}
.word{font-size:230px;font-weight:900;letter-spacing:-.06em;color:var(--fg);animation:wipe 1s cubic-bezier(.7,0,.2,1) .7s both}
.end .p{font-size:48px;animation:rise .8s cubic-bezier(.16,1,.3,1) 1.5s both}
